const progressBar=document.getElementById('progressBar');const backTop=document.getElementById('backTop');const menuButton=document.getElementById('menuButton');const phaseNav=document.getElementById('phaseNav');const navLinks=[...phaseNav.querySelectorAll('a')];const tracked=navLinks.map(link=>({link,section:document.querySelector(link.getAttribute('href'))})).filter(item=>item.section);function updateScroll(){const max=document.documentElement.scrollHeight-innerHeight;progressBar.style.width=`${max?scrollY/max*100:0}%`;backTop.classList.toggle('visible',scrollY>700);let current=tracked[0];tracked.forEach(item=>{if(item.section.getBoundingClientRect().top<180)current=item});navLinks.forEach(link=>link.classList.toggle('active',current&&link===current.link))}addEventListener('scroll',updateScroll,{passive:true});addEventListener('resize',updateScroll);updateScroll();menuButton.addEventListener('click',()=>{const open=phaseNav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open));menuButton.querySelector('span').textContent=open?'−':'+'});navLinks.forEach(link=>link.addEventListener('click',()=>{phaseNav.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.querySelector('span').textContent='+'}));backTop.addEventListener('click',()=>scrollTo({top:0,behavior:'smooth'}));
